// @/components/GununKelimesiKarti.tsx
import React from "react";
import { KURUMSAL } from "@/lib/dictionaryConstants";
import { ExtendedDictionaryItem } from "@/types/dictionary";
import { tanimlariBicimlendir, kaynagiDuzenle, type TemaTipi } from "@/utils/helpers";
import { GraphHelpers } from "next/dist/compiled/webpack/webpack";
interface GununKelimesiKartiProps {
  gununKelimesi: ExtendedDictionaryItem;
  karanlikMod: boolean;
  metinBoyutu: number;
  tema: TemaTipi; 
  onClick: () => void;
}

export default function GununKelimesiKarti({
  gununKelimesi,
  karanlikMod,
  metinBoyutu,
  tema,
  onClick,
}: GununKelimesiKartiProps) {
  // Veri yoksa bileşeni boş (null) döndürerek güvenli hale getiriyoruz
  if (!gununKelimesi) return null;

  const arkaPlanRengi = karanlikMod ? "#1e293b" : KURUMSAL.kirmiziAcik;

  return (
    <div
      onClick={onClick}
      style={{
        padding: "16px 20px",
        backgroundColor: arkaPlanRengi,
        borderLeft: `5px solid ${KURUMSAL.kirmizi}`,
        borderRadius: "8px",
        marginBottom: "20px",
        boxShadow: "0 2px 6px rgba(0,0,0,0.05)",
        cursor: "pointer",
        textAlign: "left",
      }}
      role="button"
      tabIndex={0}
      aria-label="Günün kelimesi detaylarını aç"
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span
          style={{
            color: KURUMSAL.kirmizi,
            fontWeight: "bold",
            fontSize: `${metinBoyutu * 0.85}px`,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
          }}
        >
          🌟 Günün Kelimesi
        </span>
        {gununKelimesi.dialect && (
          <span
            style={{
              fontSize: `${metinBoyutu * 0.75}px`,
              fontWeight: "bold",
              color: gununKelimesi.dialect === "BATI" ? "#16a34a" : "#2563eb",
              backgroundColor: gununKelimesi.dialect === "BATI" ? "#16a34a15" : "#2563eb15",
              padding: "3px 8px",
              borderRadius: "12px",
            }}
          >
            {gununKelimesi.dialect === "BATI" ? "Batı Adıgece" : "Doğu Kabardeyce"}
          </span>
        )}
      </div>
      
      <div
        style={{
          fontSize: `${metinBoyutu * 1.25}px`,
          fontWeight: "bold",
          color: tema.yaziAna,
          marginTop: "4px",
        }}
      >
        {gununKelimesi.kelime}
      </div>
      
      {/* Yardımcı dosyamızdan gelen formatlama fonksiyonu */}
      {tanimlariBicimlendir(
        gununKelimesi.tanim ??"",
        tema,
        gununKelimesi.kelime,
        metinBoyutu,
        kaynagiDuzenle(gununKelimesi.kaynak_sozluk)
      )}
    </div>
  );
}